"""Exercise data for Maths 12 Ch 7. Each indefinite entry is verified numerically: d/dx F(x) must equal f(x)."""
import math

ENV = dict(sin=math.sin, cos=math.cos, tan=math.tan, exp=math.exp, log=math.log, sqrt=math.sqrt, atan=math.atan,
           asin=math.asin, acos=math.acos, pi=math.pi, abs=abs, a=1.3, b=0.4, m=3.0, n=3.0, al=0.5, c=0.8)

# (tag, question text, answer text, hint, integrand f(x), antiderivative F(x), sample points)
IND = []
DEF = []


def A(tag, q, ans, hint, f, F, pts=(0.35, 0.6, 0.85)):
    IND.append((tag, q, ans, hint, f, F, pts))


def D(tag, q, ans, hint, f, lo, hi, val, check=True):
    DEF.append((tag, q, ans, hint, f, lo, hi, val, check))


def verify():
    bad = []
    for tag, q, ans, hint, f, F, pts in IND:
        try:
            ff = eval('lambda x: ' + f, ENV)
            FF = eval('lambda x: ' + F, ENV)
            for x in pts:
                h = 1e-5
                d = (FF(x + h) - FF(x - h)) / (2 * h)
                if abs(d - ff(x)) > 1e-4 * (1 + abs(ff(x))):
                    bad.append((tag, x, d, ff(x)))
                    break
        except Exception as e:
            bad.append((tag, 'error', str(e)))
    for tag, q, ans, hint, f, lo, hi, val, check in DEF:
        if not check:
            continue
        try:
            ff = eval('lambda x: ' + f, ENV)
            l, h_ = eval(lo, ENV), eval(hi, ENV)
            v = eval(val, ENV)
            N = 4000
            hh = (h_ - l) / N
            s = ff(l) + ff(h_)
            for i in range(1, N):
                s += (4 if i % 2 else 2) * ff(l + i * hh)
            s *= hh / 3
            if abs(s - v) > 1e-4 * (1 + abs(v)):
                bad.append((tag, 'def', s, v))
        except Exception as e:
            bad.append((tag, 'error', str(e)))
    return bad


